SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
IF SCHEMA_ID(N'sales') IS NULL EXEC(N'CREATE SCHEMA [sales]');
CREATE TABLE [sales].[Analytics] (
  [region] int NOT NULL,
  [amount] int NOT NULL,
  [note] varchar(20) COLLATE SQL_Latin1_General_CP1_CI_AS NULL
);
CREATE TABLE [sales].[Disabled] (
  [id] int NOT NULL,
  [code] int NULL
);
CREATE TABLE [sales].[Events] (
  [id] int NOT NULL,
  [day_id] int NOT NULL,
  [note] varchar(20) COLLATE SQL_Latin1_General_CP1_CI_AS NULL
);
CREATE TABLE [sales].[Heap] (
  [id] int NOT NULL,
  [note] varchar(20) COLLATE SQL_Latin1_General_CP1_CI_AS NULL
);
CREATE TABLE [sales].[Items] (
  [id] int NOT NULL,
  [email] nvarchar(80) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
  [active] bit NOT NULL,
  [payload] nvarchar(80) COLLATE SQL_Latin1_General_CP1_CI_AS NULL
);
CREATE UNIQUE NONCLUSTERED INDEX [UX_Disabled_code] ON [sales].[Disabled] ([code] ASC) WITH (IGNORE_DUP_KEY=OFF, PAD_INDEX=OFF, ALLOW_ROW_LOCKS=ON, ALLOW_PAGE_LOCKS=ON, OPTIMIZE_FOR_SEQUENTIAL_KEY=OFF);
CREATE CLUSTERED INDEX [CX_Events] ON [sales].[Events] ([id] ASC, [day_id] DESC) WITH (IGNORE_DUP_KEY=OFF, PAD_INDEX=OFF, ALLOW_ROW_LOCKS=ON, ALLOW_PAGE_LOCKS=ON, OPTIMIZE_FOR_SEQUENTIAL_KEY=OFF);
CREATE NONCLUSTERED INDEX [IX_Heap_cover] ON [sales].[Heap] ([id] DESC) INCLUDE ([note]) WITH (IGNORE_DUP_KEY=OFF, PAD_INDEX=OFF, ALLOW_ROW_LOCKS=ON, ALLOW_PAGE_LOCKS=ON, OPTIMIZE_FOR_SEQUENTIAL_KEY=OFF);
ALTER TABLE [sales].[Items] ADD CONSTRAINT [PK_Items] PRIMARY KEY CLUSTERED ([id] ASC) WITH (IGNORE_DUP_KEY=OFF);
CREATE UNIQUE NONCLUSTERED INDEX [UX_Items_active_email] ON [sales].[Items] ([email] DESC) INCLUDE ([payload]) WHERE ([active]=(1) AND [email] IS NOT NULL) WITH (IGNORE_DUP_KEY=OFF, FILLFACTOR=80, PAD_INDEX=ON, ALLOW_ROW_LOCKS=ON, ALLOW_PAGE_LOCKS=ON, OPTIMIZE_FOR_SEQUENTIAL_KEY=OFF);
CREATE NONCLUSTERED INDEX [IX_Items_disabled] ON [sales].[Items] ([payload] ASC) INCLUDE ([active]) WITH (IGNORE_DUP_KEY=OFF, PAD_INDEX=OFF, ALLOW_ROW_LOCKS=ON, ALLOW_PAGE_LOCKS=ON, OPTIMIZE_FOR_SEQUENTIAL_KEY=OFF);
ALTER INDEX [UX_Disabled_code] ON [sales].[Disabled] DISABLE;
ALTER INDEX [IX_Items_disabled] ON [sales].[Items] DISABLE;
